  mcardVal:        { fontSize:28, fontWeight:700 },
  toolbar:         { display:'flex', alignItems:'center', justifyContent:'space-between', marginBottom:10, gap:8 },
  filtres:         { display:'flex', gap:6 },
  filtreBtn:       { display:'flex', alignItems:'center', gap:6, padding:'6px 14px', background:'transparent', border:'1px solid rgba(255,255,255,0.09)', borderRadius:6, color:'#7a8394', fontSize:12, cursor:'pointer', transition:'all 0.15s' },
  filtreBtnActive: { background:'rgba(0,212,170,0.10)', borderColor:'rgba(0,212,170,0.28)', color:'#00d4aa' },
