  btnTrash:        { padding:'5px 7px', background:'rgba(255,71,87,0.07)', border:'1px solid rgba(255,71,87,0.16)', borderRadius:6, color:'#ff4757', cursor:'pointer', display:'flex', alignItems:'center' },
};
